package dev.ipf.whitenoise.android.media

import java.io.ByteArrayOutputStream
import java.util.Base64

// Test-only video helpers for #3376. The readers below are deliberately independent of the production scrubber:
// they parse only what the assertions need, so a scrubber bug cannot hide behind a shared parser.

/** The committed tagged fixtures, generated by scripts/generate_video_metadata_fixtures.sh. */
internal val VIDEO_FIXTURES =
    listOf("mp4-tagged.mp4", "mov-quicktime-keys.mov", "mp4-timecode.mp4", "mkv-tagged.mkv", "webm-live-tagged.webm")

/** Decodes one committed fixture from the JVM test resources. */
internal fun videoFixture(name: String): ByteArray {
    val stream = checkNotNull(VideoFixtureMarker::class.java.getResourceAsStream("/video-metadata/$name.b64")) { name }
    return Base64.getMimeDecoder().decode(stream.use { it.readBytes() })
}

/** Anchors resource lookups to this test source set. */
private object VideoFixtureMarker

/**
 * The QuickTime fixture with Apple's `appl` vendor code written into every handler's component manufacturer and
 * every audio and video sample entry's vendor, as QuickTime writers record them.
 */
internal fun appleVendorMov(): ByteArray {
    val bytes = videoFixture("mov-quicktime-keys.mov")
    val iso = TestIso(bytes)
    val boxes = iso.descendants()
    val appl = ascii("appl")
    boxes.filter { it.type == "hdlr" }.forEach { appl.copyInto(bytes, it.payload + 12) }
    boxes.filter { it.type == "stsd" }.forEach { stsd ->
        iso.children(stsd.payload + 8, stsd.end).forEach { entry -> appl.copyInto(bytes, entry.payload + 12) }
    }
    return bytes
}

/**
 * A file shaped like a Canon CR3 raw photo, following its published layout: a `crx ` brand, a Canon `uuid` box in the
 * movie holding the compressor version and TIFF/EXIF/GPS blocks, an image track with a video handler, a timed
 * metadata track, and top-level `uuid` boxes for XMP and the preview. Every value is fake. No real CR3 was available.
 */
internal fun cr3ShapedPhoto(): ByteArray {
    val canon =
        isoBox(
            "uuid",
            uuid("85c0b687820f11e08111f4ce462b6a48"),
            isoBox("CNCV", ascii("CanonCR3_001/01.09.00/00.00.00")),
            isoBox("CMT1", ascii("II*\u0000WNPrivateCanon EOS R5")),
            isoBox("CMT4", ascii("II*\u0000WNPrivateGPS 48N 2E")),
        )
    return syntheticMovie(
        listOf(SyntheticTrack("vide", samples(listOf(64), 0x11)), SyntheticTrack("meta", samples(listOf(8), 0x51))),
        movieExtras = listOf(canon),
        topLevelExtras =
            listOf(
                isoBox("uuid", uuid("be7acfcb97a942e89c71999491e3afac"), ascii("<x:xmpmeta>WNPrivateXmp</x:xmpmeta>")),
                isoBox("uuid", uuid("eaf42b5e1c984b88b9fbb7dc406e4d16"), isoBox("PRVW", ascii("WNPrivatePreview"))),
            ),
        brands = listOf("crx ", "crx ", "isom"),
    ).bytes
}

/** An AVIF image sequence shaped file: an `avis` brand and an image track that uses the video handler. */
internal fun avifSequenceShaped(): ByteArray =
    syntheticMovie(
        listOf(SyntheticTrack("vide", samples(listOf(32, 32), 0x21))),
        movieExtras = listOf(isoBox("udta", ascii("WNPrivateSequence"))),
        brands = listOf("avis", "avif", "msf1", "miaf"),
    ).bytes

/** A HEIC still image: a `heic` brand, a top-level `meta` box and media data, without a movie. */
internal fun heicShapedImage(): ByteArray {
    val handler = isoFullBox("hdlr", 0, 0, ByteArray(4), ascii("pict"), ByteArray(12), ByteArray(1))
    return concat(
        isoBox("ftyp", ascii("heic"), beBytes(0, 4), ascii("mif1heic")),
        isoFullBox("meta", 0, 0, handler),
        isoBox("mdat", ByteArray(16) { 1 }),
    )
}

/** A valid WebM header and Segment with one audio TrackEntry, read to its end without a refusal. */
internal fun audioOnlyWebm(): ByteArray {
    val entry = ebml(0xAEL, ebml(0xD7L, byteArrayOf(1)), ebml(0x83L, byteArrayOf(2)), ebml(0x86L, ascii("A_OPUS")))
    return concat(ebmlHeader("webm"), ebml(0x18538067L, ebml(0x1654AE6BL, entry)))
}

/**
 * A valid WebM header and Segment whose walk is refused before its video track list: an element in the Segment
 * declares a size beyond it. The video TrackEntry after it is never reached.
 */
internal fun matroskaRefusedBeforeTracks(): ByteArray {
    val video = ebml(0x1654AE6BL, ebml(0xAEL, ebml(0xD7L, byteArrayOf(1)), ebml(0x83L, byteArrayOf(1))))
    val overrun = concat(ebmlId(0x1549A966L), ebmlSize(500), ByteArray(4))
    return concat(ebmlHeader("webm"), ebml(0x18538067L, overrun, video))
}

/**
 * A 128-byte ID3v1 tag as audio tools append it after an `.m4a` movie: `TAG`, the title, artist, album, year and
 * comment fields, and a genre byte. It is not a box, so the ISO BMFF walk refuses at it.
 */
internal fun id3v1Tag(): ByteArray =
    concat(
        ascii("TAG"),
        ascii("Song".padEnd(30, '\u0000')),
        ascii("Band".padEnd(30, '\u0000')),
        ascii("Album".padEnd(30, '\u0000')),
        ascii("2024"),
        ByteArray(30),
        byteArrayOf(-1),
    )

/** An audio-only `.m4a` movie, with the iTunes audio brand, followed by an ID3v1 tag. */
internal fun m4aWithId3v1Tag(): ByteArray {
    val audio = listOf(SyntheticTrack("soun", samples(listOf(8, 8), 0x41)))
    return concat(syntheticMovie(audio, brands = listOf("M4A ", "M4A ", "isom")).bytes, id3v1Tag())
}

/** An audio-only WebM followed by stray bytes that are not an EBML element, so its walk refuses after its tracks. */
internal fun audioOnlyWebmWithJunk(): ByteArray = concat(audioOnlyWebm(), ByteArray(8) { 0x55 })

/**
 * A WebM whose first Segment is audio-only and complete, and whose second Segment is refused before its video track
 * list: the first Segment's complete list says nothing about the second's tracks.
 */
internal fun audioSegmentThenRefusedWebm(): ByteArray {
    val audio = ebml(0xAEL, ebml(0xD7L, byteArrayOf(1)), ebml(0x83L, byteArrayOf(2)), ebml(0x86L, ascii("A_OPUS")))
    val video = ebml(0x1654AE6BL, ebml(0xAEL, ebml(0xD7L, byteArrayOf(1)), ebml(0x83L, byteArrayOf(1))))
    val overrun = concat(ebmlId(0x1549A966L), ebmlSize(500), ByteArray(4))
    return concat(
        ebmlHeader("webm"),
        ebml(0x18538067L, ebml(0x1654AE6BL, audio)),
        ebml(0x18538067L, overrun, video),
    )
}

/** A DV stream as ffmpeg probes it: a DIF header block, then fake frame data. */
internal fun dvShapedVideo(): ByteArray = concat(byteArrayOf(0x1F, 0x07, 0x00, 0x3F), ByteArray(476) { 0x62 })

/** The 16 bytes of the hexadecimal UUID [hex]. */
private fun uuid(hex: String): ByteArray {
    val pairs = hex.chunked(2)
    return ByteArray(pairs.size) { index -> pairs[index].toInt(16).toByte() }
}

/** How many times [text] occurs in [bytes] as ASCII. */
internal fun ByteArray.countAscii(text: String): Int {
    val needle = text.toByteArray(Charsets.US_ASCII)
    return (0..size - needle.size).count { start -> needle.indices.all { this[start + it] == needle[it] } }
}

/** Whether [bytes] contain [text] as ASCII. */
internal fun ByteArray.containsAscii(text: String): Boolean = indexOf(text.toByteArray(Charsets.US_ASCII)) >= 0

/** First index of [needle] in this array, or -1. */
internal fun ByteArray.indexOf(needle: ByteArray): Int {
    val starts = if (needle.isEmpty() || needle.size > size) IntRange.EMPTY else 0..size - needle.size
    return starts.firstOrNull { start -> needle.indices.all { this[start + it] == needle[it] } } ?: -1
}

/** Big-endian bytes of [value] in [width] bytes. */
internal fun beBytes(
    value: Long,
    width: Int,
): ByteArray = ByteArray(width) { index -> (value ushr (8 * (width - 1 - index))).toByte() }

/** The ASCII bytes of [text]. */
internal fun ascii(text: String): ByteArray = text.toByteArray(Charsets.US_ASCII)

/** Concatenates [parts]. */
internal fun concat(vararg parts: ByteArray): ByteArray {
    val out = ByteArrayOutputStream()
    parts.forEach(out::write)
    return out.toByteArray()
}

/** One box found by [TestIso]. */
internal data class TestBox(
    val type: String,
    val start: Int,
    val payload: Int,
    val end: Int,
)

/** One track found by [TestIso]: its handler type and the byte range of every sample. */
internal data class TestTrack(
    val handler: String,
    val samples: List<IntRange>,
)

/** A small, independent ISO BMFF reader for assertions. */
internal class TestIso(
    private val bytes: ByteArray,
) {
    /** Unsigned big-endian value of [width] bytes at [offset]. */
    fun be(
        offset: Int,
        width: Int,
    ): Long = (0 until width).fold(0L) { acc, i -> (acc shl 8) or (bytes[offset + i].toLong() and 0xFF) }

    /** The boxes directly inside `[start, end)`. */
    fun children(
        start: Int,
        end: Int,
    ): List<TestBox> {
        val boxes = mutableListOf<TestBox>()
        var position = start
        while (position + 8 <= end) {
            var size = be(position, 4)
            var header = 8
            if (size == 1L) {
                size = be(position + 8, 8)
                header = 16
            }
            if (size == 0L) size = (end - position).toLong()
            if (size < header || position + size > end) break
            val type = String(bytes, position + 4, 4, Charsets.ISO_8859_1)
            boxes += TestBox(type, position, position + header, (position + size).toInt())
            position += size.toInt()
        }
        return boxes
    }

    /** The top-level boxes. */
    fun top(): List<TestBox> = children(0, bytes.size)

    /** Every box reachable through the movie, track and metadata containers. */
    fun descendants(): List<TestBox> {
        val found = mutableListOf<TestBox>()

        /** Records [box] and, when it is a container this reader opens, every box inside it. */
        fun visit(box: TestBox) {
            found += box
            val start =
                when (box.type) {
                    in CONTAINERS -> box.payload
                    "meta" -> if (be(box.payload, 4) == 0L) box.payload + 4 else box.payload
                    else -> return
                }
            children(start, box.end).forEach(::visit)
        }
        top().forEach(::visit)
        return found
    }

    /** The first child of [box] with [type]. */
    fun child(
        box: TestBox,
        type: String,
    ): TestBox? = children(box.payload, box.end).firstOrNull { it.type == type }

    /** Follows a path of child types from [box]. */
    fun path(
        box: TestBox,
        vararg types: String,
    ): TestBox? = types.fold<String, TestBox?>(box) { current, type -> current?.let { child(it, type) } }

    /** The creation and modification time bytes of an `mvhd`, `tkhd` or `mdhd`. */
    fun headerTimes(box: TestBox): ByteArray {
        val width = if (bytes[box.payload].toInt() == 1) 8 else 4
        return bytes.copyOfRange(box.payload + 4, box.payload + 4 + 2 * width)
    }

    /** Every track with its handler and sample byte ranges. */
    fun tracks(): List<TestTrack> {
        val moov = top().first { it.type == "moov" }
        return children(moov.payload, moov.end).filter { it.type == "trak" }.map { trak ->
            val hdlr = checkNotNull(path(trak, "mdia", "hdlr"))
            val stbl = checkNotNull(path(trak, "mdia", "minf", "stbl"))
            TestTrack(String(bytes, hdlr.payload + 8, 4, Charsets.ISO_8859_1), sampleRanges(stbl))
        }
    }

    /** Walks `stsc`, `stsz` and `stco`/`co64` into sample byte ranges. */
    private fun sampleRanges(stbl: TestBox): List<IntRange> {
        val stsc = checkNotNull(child(stbl, "stsc"))
        val stsz = checkNotNull(child(stbl, "stsz"))
        val co64 = child(stbl, "co64")
        val stco = co64 ?: checkNotNull(child(stbl, "stco"))
        val width = if (co64 != null) 8 else 4
        val chunkCount = be(stco.payload + 4, 4).toInt()
        val runs =
            (0 until be(stsc.payload + 4, 4).toInt()).map { i ->
                be(stsc.payload + 8 + 12 * i, 4) to be(stsc.payload + 12 + 12 * i, 4)
            }
        val constant = be(stsz.payload + 4, 4)
        var sample = 0
        val ranges = mutableListOf<IntRange>()
        for (chunk in 1..chunkCount) {
            var offset = be(stco.payload + 8 + width * (chunk - 1), width).toInt()
            val perChunk = runs.last { it.first <= chunk }.second.toInt()
            repeat(perChunk) {
                val size = if (constant != 0L) constant.toInt() else be(stsz.payload + 12 + 4 * sample, 4).toInt()
                ranges += offset until offset + size
                offset += size
                sample += 1
            }
        }
        return ranges
    }

    private companion object {
        val CONTAINERS = setOf("moov", "trak", "mdia", "minf", "stbl", "dinf", "edts", "mvex", "moof", "traf", "udta")
    }
}

/** One element found by [TestEbml]. */
internal data class TestElement(
    val id: Long,
    val start: Int,
    val dataStart: Int,
    val end: Int,
)

/**
 * A small, independent EBML reader for assertions. An unknown size runs to the first following element that can
 * only appear at the Segment's level, or to the parent's end.
 */
internal class TestEbml(
    private val bytes: ByteArray,
) {
    /** The elements directly inside `[start, end)`. */
    fun children(
        start: Int,
        end: Int,
    ): List<TestElement> {
        val found = mutableListOf<TestElement>()
        var position = start
        while (position < end) {
            val element = element(position, end)
            found += element
            position = element.end
        }
        return found
    }

    /** The element at [position] inside a parent ending at [end]. */
    private fun element(
        position: Int,
        end: Int,
    ): TestElement {
        val idLength = Integer.numberOfLeadingZeros(bytes[position].toInt() and 0xFF) - 23
        val id = (0 until idLength).fold(0L) { acc, i -> (acc shl 8) or (bytes[position + i].toLong() and 0xFF) }
        val sizeAt = position + idLength
        val sizeLength = Integer.numberOfLeadingZeros(bytes[sizeAt].toInt() and 0xFF) - 23
        val raw = (0 until sizeLength).fold(0L) { acc, i -> (acc shl 8) or (bytes[sizeAt + i].toLong() and 0xFF) }
        val mask = (1L shl (7 * sizeLength)) - 1
        val dataStart = sizeAt + sizeLength
        val elementEnd = if (raw and mask == mask) openEnd(id, dataStart, end) else dataStart + (raw and mask).toInt()
        return TestElement(id, position, dataStart, elementEnd)
    }

    /** Where an unknown-size element [id] whose data starts at [start] ends: a Segment ends at the next file. */
    private fun openEnd(
        id: Long,
        start: Int,
        end: Int,
    ): Int {
        val enders = if (id == SEGMENT) setOf(SEGMENT, 0x1A45DFA3L) else SEGMENT_LEVEL
        var position = start
        while (position < end) {
            val child = element(position, end)
            if (child.id in enders) return position
            position = child.end
        }
        return end
    }

    /** The children of the first Segment. */
    fun segmentChildren(): List<TestElement> {
        val segment = children(0, bytes.size).first { it.id == SEGMENT }
        return children(segment.dataStart, segment.end)
    }

    /** The children of [element]. */
    fun children(element: TestElement): List<TestElement> = children(element.dataStart, element.end)

    companion object {
        const val SEGMENT = 0x18538067L
        const val INFO = 0x1549A966L
        const val TRACKS = 0x1654AE6BL
        const val TRACK_ENTRY = 0xAEL
        const val CLUSTER = 0x1F43B675L
        const val TAGS = 0x1254C367L
        const val ATTACHMENTS = 0x1941A469L
        const val CHAPTERS = 0x1043A770L
        const val VOID = 0xECL
        const val DATE_UTC = 0x4461L
        const val TITLE = 0x7BA9L
        const val NAME = 0x536EL
        const val MUXING_APP = 0x4D80L
        const val WRITING_APP = 0x5741L
        val SEGMENT_LEVEL =
            setOf(SEGMENT, INFO, TRACKS, CLUSTER, TAGS, ATTACHMENTS, CHAPTERS, 0x1C53BB6BL, 0x114D9B74L, 0x1A45DFA3L)
    }
}

/** An ISO box of [type] holding [parts]. */
internal fun isoBox(
    type: String,
    vararg parts: ByteArray,
): ByteArray {
    val payload = concat(*parts)
    return concat(beBytes(8L + payload.size, 4), ascii(type), payload)
}

/** An ISO box of [type] holding [parts], written with a 64-bit largesize. */
internal fun isoLargeBox(
    type: String,
    vararg parts: ByteArray,
): ByteArray {
    val payload = concat(*parts)
    return concat(beBytes(1L, 4), ascii(type), beBytes(16L + payload.size, 8), payload)
}

/** An ISO full box of [type] with [version] and [flags] before [parts]. */
internal fun isoFullBox(
    type: String,
    version: Int,
    flags: Int,
    vararg parts: ByteArray,
): ByteArray = isoBox(type, beBytes(((version.toLong() and 0xFF) shl 24) or flags.toLong(), 4), *parts)

/** The minimal variable-length size encoding of [value]. */
internal fun ebmlSize(value: Long): ByteArray {
    val length = (1..8).first { value < (1L shl (7 * it)) - 1 }
    return beBytes(value or (1L shl (7 * length)), length)
}

/** The bytes of an EBML [id], which already carries its length marker. */
internal fun ebmlId(id: Long): ByteArray = beBytes(id, (1..4).first { id < (1L shl (8 * it)) })

/** An EBML element with a known size. */
internal fun ebml(
    id: Long,
    vararg parts: ByteArray,
): ByteArray {
    val payload = concat(*parts)
    return concat(ebmlId(id), ebmlSize(payload.size.toLong()), payload)
}

/** An EBML element with the unknown (all ones) eight-byte size. */
internal fun ebmlUnknown(
    id: Long,
    vararg parts: ByteArray,
): ByteArray = concat(ebmlId(id), beBytes(0x01FFFFFFFFFFFFFFL, 8), *parts)

/** An EBML header declaring [docType]. */
internal fun ebmlHeader(docType: String = "webm"): ByteArray = ebml(0x1A45DFA3L, ebml(0x4282L, ascii(docType)))

/**
 * A minimal movie the scrubber accepts, padded with media data to exactly [size] bytes (at least 148). Readers under
 * Robolectric never decode it, so it stands in for a real clip where only the size matters.
 */
internal fun minimalMp4(size: Int): ByteArray {
    val header = minimalMp4Header(size.toLong())
    return concat(header, ByteArray(size - header.size) { 0x42 })
}

/**
 * The first bytes of a [minimalMp4] of [size] bytes: everything up to the media data's payload, so a sparse file of
 * [size] bytes that starts with them is a movie whose media data is the zero-filled rest.
 */
internal fun minimalMp4Header(size: Long): ByteArray {
    val head = concat(isoBox("ftyp", ascii("isom"), beBytes(512, 4), ascii("isomiso2")), isoBox("moov", movieHeader()))
    require(size >= head.size + 8 && size - head.size <= 0xFFFFFFFFL) { "no minimal movie of $size bytes" }
    return concat(head, beBytes(size - head.size, 4), ascii("mdat"))
}

/** A RIFF/AVI header: a real video container the scrubber does not handle, so its metadata cannot be removed. */
internal fun aviVideoBytes(size: Int = 512): ByteArray =
    concat(ascii("RIFF"), beBytes(size - 8L, 4).reversedArray(), ascii("AVI LIST"), ByteArray(size - 16) { 0x33 })

/** Little-endian bytes of [value] in [width] bytes. */
internal fun leBytes(
    value: Long,
    width: Int,
): ByteArray = beBytes(value, width).reversedArray()

/** [values] as bytes. */
internal fun byteValues(vararg values: Int): ByteArray = ByteArray(values.size) { values[it].toByte() }

/**
 * One Ogg page: the capture pattern, version 0, the beginning-of-stream flag when [beginsStream], a zero granule
 * position, [serial], a zero sequence number and checksum, then the lacing table for [payload] and the payload.
 */
internal fun oggPage(
    payload: ByteArray,
    beginsStream: Boolean,
    serial: Int = 1,
): ByteArray {
    val lacing = List(payload.size / 255) { 255.toByte() } + (payload.size % 255).toByte()
    return concat(
        ascii("OggS"),
        byteValues(0, if (beginsStream) 0x02 else 0),
        ByteArray(8),
        leBytes(serial.toLong(), 4),
        ByteArray(8),
        byteValues(lacing.size),
        lacing.toByteArray(),
        payload,
    )
}

/** An Ogg file whose streams start with [firstPackets], one beginning-of-stream page each, then one data page. */
internal fun oggFile(vararg firstPackets: ByteArray): ByteArray {
    val beginnings =
        firstPackets.mapIndexed { index, packet -> oggPage(packet, beginsStream = true, serial = index + 1) }
    return concat(*beginnings.toTypedArray(), oggPage(ByteArray(40) { 0x11 }, beginsStream = false))
}

/** The first header packets that name an Ogg stream's codec. */
internal object OggPackets {
    val vorbis = concat(byteValues(1), ascii("vorbis"), ByteArray(23))
    val opus = concat(ascii("OpusHead"), byteValues(1, 2), ByteArray(9))
    val flac = concat(byteValues(0x7F), ascii("FLAC"), byteValues(1, 0), ByteArray(40))
    val speex = concat(ascii("Speex   "), ByteArray(72))
    val theora = concat(byteValues(0x80), ascii("theora"), ByteArray(35))
    val skeleton = concat(ascii("fishead"), ByteArray(57))
    val unknown = concat(ascii("XYZcodec"), ByteArray(16))
}

/** ASF GUIDs as ASF stores them on disk, with their first three fields little-endian. */
internal object AsfGuids {
    val header =
        byteValues(0x30, 0x26, 0xB2, 0x75, 0x8E, 0x66, 0xCF, 0x11, 0xA6, 0xD9, 0x00, 0xAA, 0x00, 0x62, 0xCE, 0x6C)
    val streamProperties =
        byteValues(0x91, 0x07, 0xDC, 0xB7, 0xB7, 0xA9, 0xCF, 0x11, 0x8E, 0xE6, 0x00, 0xC0, 0x0C, 0x20, 0x53, 0x65)
    val headerExtension =
        byteValues(0xB5, 0x03, 0xBF, 0x5F, 0x2E, 0xA9, 0xCF, 0x11, 0x8E, 0xE3, 0x00, 0xC0, 0x0C, 0x20, 0x53, 0x65)
    val audioMedia =
        byteValues(0x40, 0x9E, 0x69, 0xF8, 0x4D, 0x5B, 0xCF, 0x11, 0xA8, 0xFD, 0x00, 0x80, 0x5F, 0x5C, 0x44, 0x2B)
    val videoMedia =
        byteValues(0xC0, 0xEF, 0x19, 0xBC, 0x4D, 0x5B, 0xCF, 0x11, 0xA8, 0xFD, 0x00, 0x80, 0x5F, 0x5C, 0x44, 0x2B)
    val contentDescription =
        byteValues(0x33, 0x26, 0xB2, 0x75, 0x8E, 0x66, 0xCF, 0x11, 0xA6, 0xD9, 0x00, 0xAA, 0x00, 0x62, 0xCE, 0x6C)
}

/** One ASF object: its GUID, its little-endian size including this 24-byte header, and [data]. */
internal fun asfObject(
    guid: ByteArray,
    data: ByteArray,
): ByteArray = concat(guid, leBytes(24L + data.size, 8), data)

/** A Stream Properties Object for one stream of [type], with empty error correction and type-specific data. */
internal fun asfStream(type: ByteArray): ByteArray = asfObject(AsfGuids.streamProperties, concat(type, ByteArray(38)))

/** A Header Extension Object holding [embedded] objects, such as an Extended Stream Properties Object. */
internal fun asfExtension(vararg embedded: ByteArray): ByteArray {
    val data = concat(*embedded)
    val fields = concat(ByteArray(16), byteValues(6, 0), leBytes(data.size.toLong(), 4))
    return asfObject(AsfGuids.headerExtension, concat(fields, data))
}

/** An ASF file whose Header Object holds [objects], followed by a stand-in for its Data Object. */
internal fun asfFile(vararg objects: ByteArray): ByteArray {
    val body = concat(*objects)
    val count = leBytes(objects.size.toLong(), 4)
    val header = concat(AsfGuids.header, leBytes(30L + body.size, 8), count, byteValues(1, 2))
    return concat(header, body, ByteArray(64) { 0x22 })
}

/**
 * An FLV file: its header with [flags] (0x01 video, 0x04 audio), the first previous-tag size, then one 16-byte tag
 * of each of [tagTypes] (8 audio, 9 video, 18 script data), each followed by its own size.
 */
internal fun flvFile(
    flags: Int,
    vararg tagTypes: Int,
): ByteArray {
    val tags =
        tagTypes.map { type ->
            concat(byteValues(type), beBytes(16, 3), ByteArray(7), ByteArray(16) { 0x44 }, beBytes(27, 4))
        }
    return concat(ascii("FLV"), byteValues(1, flags), beBytes(9, 4), ByteArray(4), *tags.toTypedArray())
}

/** One RealMedia chunk: [id], its size including this 10-byte header, a zero version and [body]. */
internal fun realMediaChunk(
    id: String,
    body: ByteArray,
): ByteArray = concat(ascii(id), beBytes(10L + body.size, 4), ByteArray(2), body)

/**
 * A RealMedia file with one Media Properties chunk per [mimes] entry, each with [typeData] as its type-specific data,
 * then the Data chunk unless [withData] is false.
 */
internal fun realMediaFile(
    mimes: List<String>,
    typeData: ByteArray = ByteArray(8),
    withData: Boolean = true,
): ByteArray {
    val media =
        mimes.mapIndexed { index, mime ->
            val fixed = concat(beBytes(index.toLong(), 2), ByteArray(28))
            val described = concat(fixed, byteValues(0, mime.length), ascii(mime), beBytes(typeData.size.toLong(), 4))
            realMediaChunk("MDPR", concat(described, typeData))
        }
    val header = realMediaChunk(".RMF", concat(beBytes(0, 4), beBytes(mimes.size + 2L, 4)))
    val data = if (withData) realMediaChunk("DATA", ByteArray(8)) else ByteArray(0)
    return concat(header, realMediaChunk("PROP", ByteArray(40)), *media.toTypedArray(), data)
}
